def handle_top_users(params: dict) -> tuple[int, dict]:
    by = params.get("by")
    n = params.get("n")
    if by not in ("name_length", "email_length"):
        return 400, {"error": "invalid request"}
    if not isinstance(n, str) or not n or any(c not in "0123456789" for c in n):
        return 400, {"error": "invalid request"}
    count = int(n)
    if not 1 <= count <= 10:
        return 400, {"error": "invalid request"}
    return 200, {"users": users.get_top_users(by, count)}
